import json, pathlib
OUT=pathlib.Path(__file__).parent/'site'/'content.js'
P=[{'id':'basic','name':'Basic','price':95,'kv':55,'max':400,'time':8}, {'id':'city','name':'City','price':145,'kv':80,'max':300,'time':10}, {'id':'studio','name':'Studio','price':190,'kv':110,'max':200,'time':20}, {'id':'pro','name':'Pro','price':240,'kv':135,'max':150,'time':15}]
C=[]; bonus=[]; final=[]
def chap(id,title,icon,lead,definition,example):
    d={'id':id,'title':title,'icon':icon,'lead':lead,'definition':definition,'example':example,'questions':[]};C.append(d);return d

def q(c,id,afb,type,prompt,answer,solution,hint='',**extras):
    d={'id':id,'afb':afb,'type':type,'prompt':prompt,'answer':answer,'solution':solution,'hint':hint}
    d.update(extras)
    if c=='bonus':bonus.append(d)
    elif c=='final':final.append(d)
    else:c['questions'].append(d)

def mult(id, a, b):return f'{a} · {b}'

c=chap('basis','Der Stückdeckungsbeitrag','🧮',
 'Sie arbeiten im Planungsteam einer Leipziger Leuchtenproduktion. Vor einer Engpassentscheidung müssen Sie verstehen, wie viel jedes verkaufte Produkt beiträgt.',
 '<b>Stückdeckungsbeitrag (db)</b> = <b>Nettoverkaufspreis</b> − <b>variable Stückkosten</b>. Er zeigt den Beitrag eines verkauften Stücks zur <b>Deckung der Fixkosten</b> und anschließend zum Gewinn. <b>Variable Kosten</b> verändern sich mit der Ausbringungsmenge; die betrachteten <b>Fixkosten</b> bleiben im relevanten Bereich unverändert.',
 '<b>Beispiel Basic:</b> 95,00 € (Nettoverkaufspreis) − 55,00 € (variable Stückkosten) = <b>40,00 €/Stück</b>.')
q(c,'b01',1,'number','Berechnen Sie den Stückdeckungsbeitrag der Leuchte Basic (€/Stück).',40,'95,00 € (Preis Basic) − 55,00 € (variable Stückkosten Basic) = <b>40,00 €/Stück</b>.','Ziehen Sie die variablen Kosten vom Nettoverkaufspreis ab.')
q(c,'b02',1,'single','Was sagt der Stückdeckungsbeitrag aus?','b','Der Stückdeckungsbeitrag zeigt, welcher Betrag pro Stück zur Deckung der Fixkosten und danach zum Gewinn beitragen kann.','Er ist nicht identisch mit dem Stückgewinn.',options=[['a','Gewinn nach Abzug aller fixen Kosten je Stück'],['b','Nettoverkaufspreis minus variable Stückkosten'],['c','Umsatz minus alle Fixkosten']])
q(c,'b03',2,'number','Ein neues Leuchtenmodell kostet variabel 123,00 € und wird netto für 198,00 € verkauft. Ermitteln Sie den Stückdeckungsbeitrag.',75,'198,00 € (Preis) − 123,00 € (variable Stückkosten) = <b>75,00 €/Stück</b>.','Verwenden Sie die Formel db = p − kᵥ.')
q(c,'b04',2,'multi','Ordnen Sie die Kostenarten richtig zu. Welche Kosten sind im beschriebenen Fall typischerweise variabel?',['material','pack'],'Typisch variabel sind unmittelbar verbrauchtes Fertigungsmaterial und eine stückbezogene Verpackung. Die monatliche Hallenmiete und das feste Verwaltungsgehalt sind im betrachteten Kapazitätsbereich fix.','Prüfen Sie, welche Kosten sich mit jedem zusätzlich gefertigten Stück erhöhen.',options=[['material','Material je hergestellter Leuchte'],['miete','Unveränderte Hallenmiete'],['pack','Einzelverpackung je Leuchte'],['gehalt','Festes Gehalt der Verwaltung']])
q(c,'b05',2,'match','Ordnen Sie die Begriffe ihrer Bedeutung zu.',['preis','variabel','fix','db'],'<b>Preis:</b> Nettoverkaufspreis; <b>variable Stückkosten:</b> mengenabhängige Kosten je Stück; <b>Fixkosten:</b> im Betrachtungsbereich unabhängig von der Menge; <b>db:</b> Preis − variable Stückkosten.','Jeder Begriff hat genau eine passende Beschreibung.',pairs=[['preis','Nettoverkaufspreis je Stück'],['variabel','Mengenabhängige Kosten pro Stück'],['fix','Innerhalb des betrachteten Bereichs mengenunabhängig'],['db','Preis abzüglich variabler Stückkosten']])
q(c,'b06',2,'text','Erläutern Sie in eigenen Worten, weshalb ein positiver Stückdeckungsbeitrag noch nicht mit Gewinn pro Stück gleichzusetzen ist.','self','Der <b>Stück-DB</b> ist der Beitrag nach Abzug der <b>variablen</b> Stückkosten. Die <b>Fixkosten</b> sind noch nicht abgezogen; erst ihre Deckung führt zu einem Gewinn.','Nennen Sie, welche Kosten im Stück-DB noch fehlen.')
q(c,'b07',3,'text','Ein Kollege sagt: „Das Modell Studio ist mit 80 € Stück-DB stets wirtschaftlicher als City mit 65 €.“ Beurteilen Sie diese Aussage für eine begrenzte Montagezeit.','self','Die Aussage ist <b>nicht allgemein richtig</b>. Studio benötigt 20 min je Stück: 80 € ÷ 20 = <b>4 €/min</b>. City benötigt 10 min: 65 € ÷ 10 = <b>6,50 €/min</b>. Beim Montageengpass ist City je knapper Minute günstiger.','Vergleichen Sie den DB pro Minute und nicht nur pro Stück.')
q(c,'b08',3,'single','Ein Unternehmen kann in einer Engpassstunde Produkt A (70 € DB / 35 min) oder Produkt B (45 € DB / 10 min) fertigen. Welches Produkt ist bei ausreichender Nachfrage vorrangig?','b','Produkt A: 70 € ÷ 35 min = 2 €/min; Produkt B: 45 € ÷ 10 min = 4,50 €/min. <b>Produkt B</b> hat Vorrang.','Vergleichen Sie den relativen Deckungsbeitrag.',options=[['a','Produkt A, wegen des höheren Stück-DB'],['b','Produkt B, wegen des höheren DB je Minute'],['c','Beide sind immer gleich gut']])

c=chap('engpass','Den Engpass erkennen','⏱️',
 'Für die Leuchten liegen maximale Absatzmengen und Montagezeiten vor. Sie prüfen, ob die vorhandene Anlage sämtliche Nachfrage bedienen könnte.',
 'Ein <b>Engpass</b> liegt vor, wenn die zur Befriedigung der Nachfrage benötigte <b>Kapazität</b> größer ist als die <b>verfügbare Kapazität</b>. <b>Zeitbedarf je Produkt</b> = maximale Absatzmenge · Zeit je Stück. <b>Gesamtzeitbedarf</b> = Summe der Einzelbedarfe. Beachten Sie immer einheitliche Zeiteinheiten.',
 '<b>Beispiel:</b> Basic: 400 Stück (max. Absatz) · 8 min/Stück = <b>3.200 min</b>. Insgesamt würden alle vier Leuchten <b>12.450 min</b> benötigen; verfügbar sind nur <b>9.250 min</b>.')
q(c,'e01',1,'number','Wie viele Montageminuten benötigt Basic bei voller Ausschöpfung seiner Absatzgrenze?',3200,'400 Stück (Absatzgrenze Basic) · 8 min/Stück = <b>3.200 min</b>.','Absatzmenge mit Minuten pro Stück multiplizieren.')
q(c,'e02',1,'truefalse','Liegt bereits dann ein Engpass vor, wenn ein Modell einen besonders hohen Stückdeckungsbeitrag besitzt?',False,'<b>Falsch.</b> Ein Engpass entsteht erst, wenn der benötigte Umfang einer knappen Ressource die verfügbare Kapazität übersteigt.','Ein hoher DB allein sagt nichts über den Zeitbedarf.')
q(c,'e03',2,'number','Berechnen Sie den Gesamtzeitbedarf aller vier Leuchten bei maximalem Absatz (min).',12450,'3.200 min (Basic) + 3.000 min (City) + 4.000 min (Studio) + 2.250 min (Pro) = <b>12.450 min</b>.','Addieren Sie die vier maximalen Zeitbedarfe.')
q(c,'e04',2,'number','Wie viele Minuten fehlen für die vollständige Bedienung der Nachfrage, wenn 9.250 min zur Verfügung stehen?',3200,'12.450 min (Gesamtzeitbedarf) − 9.250 min (verfügbare Montagekapazität) = <b>3.200 min Fehlbedarf</b>.','Vergleichen Sie Bedarf und Kapazität.')
q(c,'e05',2,'single','Eine Anlage ist 140 Stunden verfügbar. Wie viele Minuten sind dies?','a','140 h (Kapazität) · 60 min/h = <b>8.400 min</b>.','Eine Stunde enthält 60 Minuten.',options=[['a','8.400 Minuten'],['b','14.000 Minuten'],['c','2.333 Minuten']])
q(c,'e06',2,'multi','Welche der folgenden Umstände können zu einem betrieblichen Engpass führen?',['ausfall','personal','material'],'Ein Maschinenausfall, fehlendes Fachpersonal und nicht ausreichend verfügbares Material können Ressourcen verknappen. Ein höherer Nettoverkaufspreis allein begründet keinen Kapazitätsengpass.','Denken Sie an Produktionsfaktoren.',options=[['ausfall','Ausfall einer wichtigen Montagemaschine'],['preis','Höherer Verkaufspreis eines Produkts'],['personal','Zu wenig qualifiziertes Personal'],['material','Begrenzte Materiallieferung']])
q(c,'e07',3,'text','Für eine neue Produktionswoche werden 6.000 Maschinenminuten benötigt; verfügbar sind 6.500 Minuten. Beurteilen Sie, ob nach den vorliegenden Angaben ein Engpass besteht und welche Produktionsentscheidung daraus folgt.','self','<b>Kein Engpass:</b> 6.000 min (Bedarf) ≤ 6.500 min (Kapazität). Die Nachfrage kann vollständig hergestellt werden; eine Priorisierung der Produkte nach relativem DB ist hierfür <b>nicht notwendig</b>. Es bleiben 500 min frei.','Rechnen Sie die Differenz aus und leiten Sie daraus eine Konsequenz ab.')
q(c,'e08',3,'text','Die Montagekapazität von LichtForm beträgt 9.250 min. Die Vertriebsleitung möchte alle Absatzgrenzen vollständig bedienen. Prüfen Sie diese Forderung rechnerisch und schlagen Sie eine passende Vorgehensweise vor.','self','12.450 min (Bedarf) − 9.250 min (Kapazität) = <b>3.200 min Fehlbedarf</b>. Die Forderung ist ohne Erweiterung <b>nicht erfüllbar</b>. Deshalb muss die knappe Zeit nach dem <b>relativen Deckungsbeitrag</b> verteilt werden, um das Ergebnis zu verbessern.','Nicht nur Engpass feststellen: Konsequenz für die Reihenfolge begründen.')

c=chap('rang','Relativen DB und Rangfolge bestimmen','🏆',
 'Bei einer knappen Montageanlage ist entscheidend, wie viel Deckungsbeitrag pro Montageminute erwirtschaftet wird.',
 'Der <b>relative Deckungsbeitrag</b> ist der <b>Stückdeckungsbeitrag je Engpasseinheit</b>. Bei einem Zeitengpass gilt: <b>relativer DB = Stück-DB ÷ Minuten je Stück</b>. Ein höherer relativer DB bedeutet einen höheren Beitrag je eingesetzter knapper Minute. Daraus entsteht die <b>absteigende Fertigungsrangfolge</b>.',
 '<b>Beispiel Pro:</b> 105,00 €/Stück (Stück-DB) ÷ 15 min/Stück (Montagezeit) = <b>7,00 €/min</b>. Pro hat Rang 1; die Reihenfolge lautet <b>Pro → City → Basic → Studio</b>.')
q(c,'r01',1,'number','Ermitteln Sie den relativen Deckungsbeitrag von Pro in €/min.',7,'105,00 €/Stück (Stück-DB Pro) ÷ 15 min/Stück (Montagezeit Pro) = <b>7,00 €/min</b>.','Stück-DB durch Minuten pro Stück teilen.')
q(c,'r02',1,'order','Ordnen Sie die vier Leuchten von Rang 1 (zuerst) bis Rang 4 (zuletzt).',['pro','city','basic','studio'],'<b>Pro → City → Basic → Studio.</b> Relative DB: Pro 7,00; City 6,50; Basic 5,00; Studio 4,00 €/min.','Ordnen Sie absteigend nach €/min.',items=[['basic','Basic'],['studio','Studio'],['pro','Pro'],['city','City']])
q(c,'r03',2,'number','Berechnen Sie den relativen Deckungsbeitrag des Modells City in €/min.',6.5,'65,00 €/Stück (Stück-DB City) ÷ 10 min/Stück (Montagezeit City) = <b>6,50 €/min</b>.','Achten Sie auf den Unterschied zwischen 65 €/Stück und €/min.')
q(c,'r04',2,'match','Ordnen Sie den vier Leuchten ihren relativen Deckungsbeitrag zu.',['basic','studio','pro','city'],'Basic = <b>5,00 €/min</b>, City = <b>6,50 €/min</b>, Studio = <b>4,00 €/min</b>, Pro = <b>7,00 €/min</b>.','Berechnen Sie Stück-DB ÷ Montagezeit.',pairs=[['basic','5,00 €/min'],['studio','4,00 €/min'],['pro','7,00 €/min'],['city','6,50 €/min']])
q(c,'r05',2,'number','Eine LED-Platine hat 78,00 € Stück-DB und benötigt 12 Minuten in der Prüfung. Berechnen Sie den relativen DB in €/min.',6.5,'78,00 €/Stück (Stück-DB Platine) ÷ 12 min/Stück (Prüfdauer) = <b>6,50 €/min</b>.','Engpasseinheit ist hier die Prüfminute.')
q(c,'r06',2,'multi','Welche Aussagen zur Fertigungsrangfolge sind bei einem einzigen Engpass zutreffend?',['rel','max','zeit'],'Die Reihenfolge richtet sich nach <b>relativem DB</b>. Je Produkt darf höchstens die <b>Absatzgrenze</b> ausgeschöpft werden. Die verwendete Zeit muss die <b>Gesamtkapazität</b> einhalten. Die höchsten Preise sind nicht automatisch vorrangig.','Prüfen Sie Engpass und Absatzgrenzen.',options=[['rel','Die Reihenfolge wird nach dem relativen DB gebildet.'],['preis','Das Produkt mit dem höchsten Verkaufspreis steht immer zuerst.'],['max','Absatzobergrenzen dürfen nicht überschritten werden.'],['zeit','Der Gesamtzeitbedarf der ausgewählten Mengen ist begrenzt.']])
q(c,'r07',3,'text','Der Vertrieb möchte Studio vor City produzieren, weil Studio einen höheren Stückdeckungsbeitrag hat. Widerlegen Sie die Entscheidung rechnerisch und erklären Sie die wirtschaftliche Konsequenz.','self','Studio: 80,00 € ÷ 20 min = <b>4,00 €/min</b>; City: 65,00 € ÷ 10 min = <b>6,50 €/min</b>. City erzielt 2,50 € mehr DB pro knapper Minute und ist deshalb vorrangig.','Rechnen Sie für beide Modelle den DB je Minute aus.')
q(c,'r08',3,'single','Produkt X erzielt 110 € Stück-DB bei 20 min; Produkt Y erzielt 63 € Stück-DB bei 9 min. Welche Priorität ist richtig?','y','X: 110 € ÷ 20 = 5,50 €/min; Y: 63 € ÷ 9 = 7,00 €/min. <b>Y steht vor X</b>.','Rechnen Sie beide relativen Deckungsbeiträge aus.',options=[['x','X vor Y, weil 110 € höher als 63 € sind'],['y','Y vor X, weil 7,00 €/min höher als 5,50 €/min sind'],['g','Beide müssen stets gleichzeitig produziert werden']])

c=chap('programm','Das optimale Produktionsprogramm','🏭',
 'Sie verteilen die knappe Montagezeit Schritt für Schritt auf die vier Modelle. Begonnen wird mit dem höchsten relativen DB.',
 '<b>Optimales Produktionsprogramm:</b> die Produktionsmengen, mit denen unter den vorliegenden Annahmen (ein Engpass, konstante DB, begrenzte Nachfrage) der <b>Gesamtdeckungsbeitrag</b> maximiert wird. Vorgehen: <b>1.</b> Rang 1 bis zur Absatzgrenze fertigen, <b>2.</b> Restzeit abziehen, <b>3.</b> nächstes Modell, <b>4.</b> bei begrenzter Restzeit nur die <b>ganze</b> herstellbare Stückzahl einsetzen.',
 '<b>Beispiel:</b> Pro nutzt 150 Stück · 15 min = 2.250 min. Rest: 9.250 − 2.250 = 7.000 min. City nutzt weitere 3.000 min, Basic weitere 3.200 min; für Studio bleiben 800 min, also <b>40 Stück</b>.')
q(c,'p01',1,'number','Nach vollständiger Produktion von Pro (150 Stück) verbleiben wie viele Minuten?',7000,'9.250 min (Gesamtkapazität) − 150 Stück (Pro-Absatzgrenze) · 15 min/Stück = <b>7.000 min</b>.','Erst 150 · 15, dann von 9.250 abziehen.')
q(c,'p02',1,'single','Mit welchem Modell beginnen Sie das gewinnoptimale Produktionsprogramm?','pro','Mit <b>Pro</b>, da es mit 7,00 €/min den höchsten relativen DB besitzt.','Wählen Sie Rang 1.',options=[['basic','Basic'],['city','City'],['studio','Studio'],['pro','Pro']])
q(c,'p03',2,'number','Nachdem Pro (2.250 min) und City (3.000 min) gefertigt wurden: Wie viel Montagezeit bleibt frei?',4000,'9.250 min (Kapazität) − 2.250 min (Pro) − 3.000 min (City) = <b>4.000 min</b>.','Subtrahieren Sie die bereits genutzte Zeit.')
q(c,'p04',2,'table','Tragen Sie die <b>optimalen Produktionsmengen</b> für Basic, City, Studio und Pro ein (Stück).',[400,300,40,150],'<b>Basic:</b> 400 St.; <b>City:</b> 300 St.; <b>Studio:</b> 800 min (Restzeit) ÷ 20 min/St. = 40 St.; <b>Pro:</b> 150 St. Gesamtmenge: <b>890 St.</b>','Verteilen Sie 9.250 min in der Reihenfolge Pro, City, Basic, Studio.',fields=['Basic (St.)','City (St.)','Studio (St.)','Pro (St.)'])
q(c,'p05',2,'number','Wie viele Montageminuten werden vom optimalen Produktionsprogramm insgesamt genutzt?',9250,'2.250 min (Pro) + 3.000 min (City) + 3.200 min (Basic) + 800 min (Studio) = <b>9.250 min</b>.','Kontrollieren Sie die genutzten Minuten je Modell.')
q(c,'p06',2,'order','Ordnen Sie die Arbeitsschritte der Engpassplanung in die richtige Reihenfolge.',['rank','first','rest','next'],'1. Rangfolge anhand des relativen DB bilden → 2. obersten Rang bis maximaler Nachfrage berücksichtigen → 3. Restkapazität berechnen → 4. nächstes Produkt.','Bevor Sie produzieren, müssen Sie priorisieren.',items=[['next','Nächstes Produkt nach Rang wählen'],['rest','Restkapazität berechnen'],['rank','Rangfolge aus relativen DB bilden'],['first','Vorrangiges Produkt bis zur Absatzgrenze berücksichtigen']])
q(c,'p07',3,'text','Ein Unternehmen hat nur noch 53 Minuten für Produkt A (13 min/Stück). Die Absatzgrenze beträgt 8 Stück. Bestimmen und begründen Sie die zulässige Produktionsmenge und die verbleibende Zeit.','self','53 min (Restkapazität) ÷ 13 min/Stück = 4,0769…; es können nur <b>4 ganze Stück</b> hergestellt werden. Genutzte Zeit = 4 · 13 = <b>52 min</b>; Rest = <b>1 min</b>. Absatzgrenze 8 wird nicht überschritten.','Sie können keine Bruchteile von Produkten herstellen.')
q(c,'p08',3,'table','Neue Produktserie: Für P (90 € DB, 15 min, max. 80), Q (64 € DB, 8 min, max. 120) und R (70 € DB, 10 min, max. 90) stehen 2.500 min zur Verfügung. Ermitteln Sie die gewinnoptimalen Stückzahlen P / Q / R.',[42,120,90],'<b>Rel. DB:</b> Q: 64 € ÷ 8 min = 8 €/min; R: 70 € ÷ 10 min = 7 €/min; P: 90 € ÷ 15 min = 6 €/min. Q: 120 · 8 = 960 min, Rest 1.540; R: 90 · 10 = 900 min, Rest 640; P: 640 ÷ 15 = <b>42 ganze Stück</b>, genutzte Zeit 630 min. Es bleiben 10 min ungenutzt.','Beginnen Sie mit Q, danach R, zuletzt P.',fields=['P (St.)','Q (St.)','R (St.)'])

c=chap('ergebnis','Gesamt-DB und Betriebsergebnis','📊',
 'Nach der Produktionsplanung bewerten Sie deren wirtschaftliches Ergebnis und überprüfen die Zahlen.',
 '<b>Gesamtdeckungsbeitrag eines Produkts</b> = <b>produzierte und verkaufte Menge</b> · <b>Stückdeckungsbeitrag</b>. <b>Gesamt-DB des Programms</b> = Summe aller Produkt-DB. <b>Betriebsergebnis</b> = Gesamt-DB − <b>Fixkosten</b>. Bei positiven unveränderten Fixkosten führt das Programm mit dem höheren Gesamt-DB auch zum höheren Ergebnis.',
 '<b>Beispiel:</b> Studio: 40 Stück (optimale Menge) · 80,00 €/Stück (db) = <b>3.200,00 € DB</b>. Für alle vier Produkte: <b>54.450,00 €</b>. Abzüglich 38.000,00 € Fixkosten bleiben <b>16.450,00 € Gewinn</b>.')
q(c,'g01',1,'number','Berechnen Sie den Gesamtdeckungsbeitrag von Basic im optimalen Produktionsprogramm.',16000,'400 Stück (optimale Basic-Menge) · 40 €/Stück (Basic-db) = <b>16.000,00 €</b>.','Gesamt-DB = Menge · Stück-DB.')
q(c,'g02',1,'number','Berechnen Sie den Gesamtdeckungsbeitrag von Pro.',15750,'150 Stück (optimale Pro-Menge) · 105 €/Stück (Pro-db) = <b>15.750,00 €</b>.','Menge mal Stückdeckungsbeitrag.')
q(c,'g03',2,'number','Ermitteln Sie den Gesamtdeckungsbeitrag des gewinnoptimalen Programms aus Basic 16.000 €, City 19.500 €, Studio 3.200 € und Pro 15.750 €.',54450,'16.000 € (Basic) + 19.500 € (City) + 3.200 € (Studio) + 15.750 € (Pro) = <b>54.450,00 €</b>.','Addieren Sie alle vier Produkt-DB.')
q(c,'g04',2,'number','Ermitteln Sie das Betriebsergebnis bei 54.450 € Gesamtdeckungsbeitrag und monatlich 38.000 € Fixkosten.',16450,'54.450 € (Gesamtdeckungsbeitrag) − 38.000 € (monatliche Fixkosten) = <b>16.450 € Gewinn</b>.','Gesamtdeckungsbeitrag minus Fixkosten.')
q(c,'g05',2,'match','Ordnen Sie den Modellen die Gesamtdeckungsbeiträge des optimalen Programms zu.',['basic','city','studio','pro'],'<b>Basic:</b> 16.000 €; <b>City:</b> 19.500 €; <b>Studio:</b> 3.200 €; <b>Pro:</b> 15.750 €.','Nutzen Sie die produzierten Stückzahlen.',pairs=[['basic','16.000 €'],['city','19.500 €'],['studio','3.200 €'],['pro','15.750 €']])
q(c,'g06',2,'truefalse','Die fixen Gesamtkosten werden bei unveränderter Höhe in der Rangfolge nach relativem DB bei einem einzigen Zeitengpass nicht pro Produkt abgezogen.',True,'<b>Richtig.</b> Die Rangfolge ergibt sich aus dem Stück-DB je Engpasseinheit; unveränderte gemeinsame Fixkosten werden erst beim Betriebsergebnis berücksichtigt.','Fixkosten folgen erst nach der Summe aller Deckungsbeiträge.')
q(c,'g07',3,'text','Die Geschäftsführung fragt, warum im optimalen Produktionsprogramm trotz Rang 4 noch 40 Studio-Leuchten vorgesehen sind. Erläutern Sie das anhand der Restkapazität und des Gesamtdeckungsbeitrags.','self','Nach Pro (2.250 min), City (3.000 min) und Basic (3.200 min) bleiben <b>800 min</b> von 9.250 min Kapazität. Damit sind <b>40 Studio-Leuchten</b> (800 ÷ 20) möglich. Diese erwirtschaften 40 Stück · 80 €/St. = <b>3.200 € zusätzlichen Gesamt-DB</b>. Die anderen Modelle sind bereits an ihren Absatzgrenzen; ohne Studio würden die 800 min nicht genutzt und der Gesamt-DB wäre geringer.','Berechnen Sie die Restzeit nach Pro, City und Basic und ermitteln Sie, was Studio damit beitragen kann.')
q(c,'g08',3,'number','Der Vertrieb fertigt fälschlich nach dem höchsten Stück-DB: Pro 150 St., Studio 200 St., City 300 St., Basic 0 St. Ermitteln Sie den Ergebnisnachteil gegenüber dem optimalen Gesamt-DB von 54.450 €.',3200,'Falscher Gesamt-DB = 150 · 105 € (Pro) + 200 · 80 € (Studio) + 300 · 65 € (City) = <b>51.250 €</b>. Ergebnisnachteil = 54.450 € (optimaler DB) − 51.250 € (falscher DB) = <b>3.200 €</b>.','Vergleichen Sie die Gesamtdeckungsbeiträge, weil die Fixkosten gleich sind.')

c=chap('entscheiden','Entscheidungen begründen','🧠',
 'Sie sind nun in der Rolle einer Produktionsleitung: Berechnen reicht nicht immer. Sie müssen auch eine betriebswirtschaftlich nachvollziehbare Empfehlung formulieren.',
 '<b>Wirtschaftliche Priorität:</b> Zuerst wird die knappe Kapazität für das Produkt mit dem <b>höchsten relativen DB</b> verwendet (bis zur Absatzgrenze). <b>Qualitative Kriterien</b> wie Kundenbeziehungen, Lieferfähigkeit, Qualität und Image können ergänzend relevant sein. Die berechnete optimale Lösung gilt für die <b>im Sachverhalt genannten Annahmen</b>.',
 '<b>Beispiel:</b> City erzielt 6,50 €/min und Studio 4,00 €/min. Bei knapper Montagezeit hat City Vorrang. Bei vertraglich zugesagten Lieferungen müssen aber auch Lieferpflichten geprüft werden.')
q(c,'d01',1,'single','Welche Kennzahl bestimmt die Vorrangstellung, wenn genau eine knappe Fertigungsressource vorhanden ist?','rel','Entscheidend ist der <b>relative Deckungsbeitrag pro Engpasseinheit</b>.','Welche Kennzahl setzt den DB zur knappen Ressource ins Verhältnis?',options=[['rel','Relativer Deckungsbeitrag'],['p','Höchster Nettoverkaufspreis'],['f','Fixkosten je Produkt']])
q(c,'d02',1,'truefalse','Wenn ausschließlich ganze Produkte gefertigt werden können, darf eine errechnete Produktionsmenge von 12,8 Stück auf 13 Stück aufgerundet werden, auch wenn dadurch die Zeitkapazität überschritten wird.',False,'<b>Falsch.</b> Bei 12,8 möglichen Einheiten dürfen ohne zusätzliche Kapazität höchstens <b>12 ganze Stück</b> produziert werden.','Kapazitätsgrenzen sind verbindlich.')
q(c,'d03',2,'number','Bei 10.000 statt 9.250 verfügbaren Montageminuten: Wie viele Studio-Leuchten sind nach Pro (2.250 min), City (3.000 min) und Basic (3.200 min) vollständig produzierbar?',77,'Rest = 10.000 min (neue Kapazität) − 2.250 min (Pro) − 3.000 min (City) − 3.200 min (Basic) = 1.550 min; 1.550 min ÷ 20 min/Studio = <b>77 ganze Stück</b> (10 min Rest).','Die anderen Absatzgrenzen bleiben gleich.')
q(c,'d04',2,'multi','Welche Aspekte sind neben der rein rechnerischen Rangfolge bei einer Produktionsentscheidung sinnvoll zu prüfen?',['liefer','kunde','qual'],'<b>Lieferpflichten</b>, <b>Kundenbeziehungen</b> und <b>Qualitätsrisiken</b> können Entscheidungen beeinflussen. Die Lieblingsfarbe der Teamleitung ist kein sachliches betriebswirtschaftliches Kriterium.','Denken Sie an Risiken und Kunden.',options=[['liefer','Verbindliche Liefertermine'],['kunde','Langfristige Kundenbeziehungen'],['qual','Besondere Anforderungen an die Produktqualität'],['farbe','Persönlicher Farbgeschmack der Leitung']])
q(c,'d05',2,'number','Bei einem Helmmodell wurden für 220 Stück insgesamt 26.400 € Deckungsbeitrag errechnet. Wie hoch ist der Stück-DB?',120,'26.400 € (Gesamt-DB) ÷ 220 Stück (Produktionsmenge) = <b>120,00 €/Stück</b>.','Stückwert = Gesamtwert ÷ Menge.')
q(c,'d06',2,'number','Das Helmmodell aus der vorherigen Frage benötigt 8 min je Stück. Berechnen Sie den relativen DB in €/min. Gegeben: Stück-DB 120 €.',15,'120 €/Stück (vorgegebener Stück-DB) ÷ 8 min/Stück (Fräszeit) = <b>15,00 €/min</b>.','Die Werte stehen vollständig in dieser Frage.')
q(c,'d07',3,'text','Beurteilen Sie die Aussage: „Das gewinnoptimale Produktionsprogramm ist unabhängig von der Absatzgrenze; wir können stets nur das beste Modell herstellen.“','self','<b>Falsch.</b> Auch das vorrangige Produkt kann nur <b>bis zur maximal absetzbaren Menge</b> verkauft werden. Verbleibende Kapazität wird danach dem Produkt mit dem nächsthöheren relativen DB zugewiesen.','Berücksichtigen Sie Absatz und Kapazität gleichzeitig.')
q(c,'d08',3,'text','Die Marketingabteilung möchte alle vier Leuchtenmodelle trotz des Montageengpasses im Sortiment behalten. Beurteilen Sie diesen Wunsch aus absatzpolitischer Sicht anhand zweier qualitativer Kriterien.','self','Eine <b>breite Sortimentsauswahl</b> kann unterschiedliche Kundenwünsche erfüllen und die <b>Kundenbindung</b> stärken. Auch das <b>Image</b> als vielseitiger Anbieter kann relevant sein. Wirtschaftlich bleibt die Engpassrangfolge wichtig: Im optimalen Programm werden bereits <b>40 Studio-Leuchten</b> hergestellt, weil nach den vorrangigen Modellen noch <b>800 min</b> verfügbar sind. Eine abweichende Mengenverteilung müsste auf ihre Auswirkung auf den Gesamt-DB geprüft werden.','Denken Sie an Sortimentsvielfalt, Kundenwünsche und die wirtschaftliche Rangfolge; beachten Sie die noch möglichen 40 Studio-Stück.')

# Bonus: nur AFB 2–3
q('bonus','x01',2,'number','Bonus – Prüfanlage: 108.000 verfügbare Minuten. Wie viele Stunden sind das?',1800,'108.000 min (Prüfkapazität) ÷ 60 min/h = <b>1.800 h</b>.','Minuten durch 60 teilen.')
q('bonus','x02',2,'number','Bonus – Ein Rest von 1.275 min steht für ein Teil mit 10 min/Stück zur Verfügung. Wie viele ganze Teile können gefertigt werden?',127,'1.275 min (Restzeit) ÷ 10 min/Stück = 127,5; es können <b>127 ganze Stück</b> gefertigt werden, 5 min bleiben frei.','Bruchteile dürfen nicht produziert werden.')
q('bonus','x03',2,'single','Bonus – Bei 13 Stunden verfügbarer Fertigungszeit und 900 min Bedarf liegt …','eng','13 h · 60 min/h = 780 min; Bedarf 900 min > 780 min. <b>Es liegt ein Engpass von 120 min vor.</b>','Rechnen Sie zuerst die Stunden um.',options=[['kein','kein Engpass vor'],['eng','ein Engpass von 120 min vor'],['eng2','ein Engpass von 13 min vor']])
q('bonus','x04',3,'text','Bonus – Ein Produktionsleiter lässt ausschließlich das Produkt mit dem höchsten relativen DB fertigen und nutzt dadurch nur die Hälfte der vorhandenen Zeit. Entwickeln Sie eine bessere Vorgehensweise.','self','Er muss zuerst das vorrangige Produkt <b>bis zur Absatzgrenze</b> einplanen und anschließend die <b>verbleibende Restkapazität</b> schrittweise mit den Produkten der nächsten Ränge belegen, sofern deren Stück-DB positiv und Absatz vorhanden ist. Eine reine Beschränkung auf Rang 1 verschenkt DB.','Der erste Rang ist ein Anfang, nicht das Ende der Planung.')
q('bonus','x05',3,'table','Bonus – Produktionsplanung: A (db 32 €, 4 min, max. 60), B (db 45 €, 9 min, max. 50), C (db 24 €, 3 min, max. 70). Verfügbar sind 600 min. Welche Stückzahlen A/B/C sind nach relativer Rangfolge sinnvoll?',[60,16,70],'<b>Rel. DB:</b> A 32 ÷ 4 = 8 €/min; B 45 ÷ 9 = 5 €/min; C 24 ÷ 3 = 8 €/min. Rang A/C gleich: beide voll produzieren, Zeit 60 · 4 + 70 · 3 = 450 min. Rest 150 min. B: 150 ÷ 9 = <b>16 Stück</b>, Rest 6 min. A=60, B=16, C=70.','A und C sind gleichrangig; beide haben 8 €/min.',fields=['A (St.)','B (St.)','C (St.)'])
q('bonus','x06',3,'text','Bonus – Die Produktionsleitung möchte ausschließlich die beiden Leuchten mit den höchsten Nettoverkaufspreisen fertigen. Widerlegen oder bestätigen Sie diesen Vorschlag rechnerisch mithilfe der relativen Deckungsbeiträge und nennen Sie ein absatzpolitisches Risiko.','self','<b>Die beiden höchsten Preise</b> haben Pro (240 €/St.) und Studio (190 €/St.). Entscheidend ist jedoch der <b>relative DB</b>: Pro 105 € ÷ 15 min = <b>7,00 €/min</b>; City 65 € ÷ 10 min = <b>6,50 €/min</b>; Basic 40 € ÷ 8 min = <b>5,00 €/min</b>; Studio 80 € ÷ 20 min = <b>4,00 €/min</b>. Daher wäre „nur Pro und Studio“ keine sinnvolle Engpassstrategie. <b>Absatzpolitisch</b> drohen bei Konzentration auf zwei Modelle der Verlust von Kundengruppen und geringere Sortimentsvielfalt. Nach der Absatzgrenze von Pro müssen weitere Modelle entsprechend ihrer relativen DB berücksichtigt werden.','Ermitteln Sie zuerst die beiden höchsten Verkaufspreise und vergleichen Sie diese Entscheidung anschließend mit dem DB je Montageminute.')
q('bonus','x07',2,'number','Bonus – Bei 3.600 min Kapazität werden 450 Stück eines Produkts mit 6 min/Stück gefertigt. Wie viel Restkapazität bleibt?',900,'3.600 min (Kapazität) − 450 Stück (Menge) · 6 min/Stück = <b>900 min</b>.','Benötigte Zeit abziehen.')
q('bonus','x08',3,'text','Bonus – Erklären Sie, warum das Verfahren „höchster relativer DB zuerst“ nur bei passenden Annahmen zuverlässig ist und eine Produktion ganzer Stückzahlen zusätzliche Kontrollen verlangt.','self','Das Rangverfahren setzt insbesondere einen <b>einzigen relevanten Engpass</b>, bekannte konstante Stück-DB und Zeitbedarfe sowie begrenzte Absatzmengen voraus. Bei <b>ganzen Stückzahlen</b> können Restminuten entstehen; das Ergebnis muss auf Kapazitätsgrenzen und gegebenenfalls alternative Kombinationen geprüft werden.','Denken Sie an Annahmen des Modells und an Rundungen.')

